#include <stdio.h>

int main(void) {
    long int n_segundos;
    scanf("%ld", &n_segundos);
    printf("%d\n", (int) (n_segundos / 3600));
    printf("%d\n", (int) ((n_segundos % 3600) / 60));
    printf("%d\n", (int) (n_segundos % 60));
    return 0;
}

#include <stdio.h>

int main(void) {
    int num, c, d, u, num_inv;
    scanf("%d", &num);
    c = num / 100;
    d = (num % 100) / 10;
    u = num % 10;
    num_inv = u * 100 + d * 10 + c;
    printf("%d\n", num);
    printf("%d\n", num_inv);
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    double pr1, pr2, mf;
    scanf("%lf %lf", &pr1, &pr2);
    mf = (pr1 + pr2) / 2.0;
    printf("%d\n", (int)(mf + 1e-9));
    printf("%d\n", (int)round(mf + 1e-9));
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    double xnum1, xnum2, xnum3, x;
    scanf("%lf %lf %lf", &xnum1, &xnum2, &xnum3);
    x = xnum1 + xnum2 / (xnum3 + xnum1) + 2.0 * (xnum1 - xnum2) + log(64.0) / log(2.0);
    printf("%.2f\n", x);
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    int termo, razao, quinto;
    scanf("%d %d", &termo, &razao);
    quinto = termo * (int)round(pow(razao, 4));
    printf("%d\n", quinto);
    return 0;
}

#include <stdio.h>

int main(void) {
    double tempo, vel, dist, litros;
    scanf("%lf %lf", &tempo, &vel);
    dist = tempo * vel;
    litros = dist / 12.0;
    printf("%.2f\n", vel);
    printf("%.2f\n", tempo);
    printf("%.2f\n", dist);
    printf("%.2f\n", litros);
    return 0;
}

#include <stdio.h>

int main(void) {
    double valor, taxa, prest;
    int tempo;
    scanf("%lf %lf %d", &valor, &taxa, &tempo);
    prest = valor + (valor * (taxa / 100.0) * tempo);
    printf("%.2f\n", prest);
    return 0;
}

